import { createWebhooks } from '../src/index.js';
import { memoryStore } from '../src/stores/memory.js';
import { startReceiver } from './receiver.js';

const customer = await startReceiver(); // stands in for your customer's server
// allowHttp + allowPrivateNetworks are for this local demo only; production defaults are strict.
const webhooks = createWebhooks({
  store: memoryStore(),
  allowHttp: true,
  allowPrivateNetworks: true,
});
const endpoint = await webhooks.createEndpoint({ url: customer.url, events: ['invoice.*'] });
customer.setSecret(endpoint.secret); // the customer stores the whsec_ secret you show them once
const result = await webhooks.send({ type: 'invoice.paid', data: { invoiceId: 'inv_1' } });
console.log(result.deliveries); // [{ endpointId, status: 'success', attempts: 1 }]
customer.close();
